  sheet: "CƠ_DH1",
  tab: "DH1",
  requestType: "Cơ",
};

const normalize = (value) => String(value ?? "")
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .replace(/đ/g, "d")
  .replace(/Đ/g, "D")
  .toLowerCase()
  .replace(/\s+/g, " ")
  .trim();

const text = (value) => String(value ?? "").trim();

const inputRows = $input.all().map(({ json }) => json);
const numberedColumnKeys = new Map();
for (const row of inputRows) {
  for (const [key, value] of Object.entries(row)) {
    const match = text(value).match(/^\((\d{1,2})\)$/);
    if (match) numberedColumnKeys.set(Number(match[1]), key);
  }
  if (numberedColumnKeys.size) break;
}

function valueOf(row, aliases, numberedColumn) {
  const entries = Object.entries(row).map(([key, value]) => [normalize(key), value]);
  for (const alias of aliases) {
    const exact = entries.find(([key]) => key === alias);
    if (exact) return text(exact[1]);
  }
  for (const alias of aliases) {
    const partial = entries.find(([key]) => key.includes(alias));
    if (partial) return text(partial[1]);
  }
  const fallbackKey = numberedColumnKeys.get(numberedColumn);
  if (fallbackKey) return text(row[fallbackKey]);
  return "";
}

function sourceDate(value) {
  const match = text(value).match(/(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})/);
  if (!match) return null;
  const year = match[3].length === 2 ? 2000 + Number(match[3]) : Number(match[3]);
  const date = new Date(Date.UTC(year, Number(match[2]) - 1, Number(match[1])));
  return Number.isNaN(date.getTime()) ? null : date.toISOString().slice(0, 10);
}

function sourceKey(record) {
  const unit = text(record.unit).toUpperCase().replace(/\s+/g, " ");
  return [
    record.sourceSpreadsheetId,
    record.sourceSheet,
    record.requestType,
    text(record.stt).replace(/\.0$/, ""),
    sourceDate(record.detectedAtRaw),
    unit === "S1" || unit === "S2" ? unit : "COMMON",
    normalize(record.positionRaw),
    normalize(record.deviceRaw),
  ].join("|");
}

const rawRecords = inputRows.map((row) => {
  const stt = valueOf(row, ["stt (vh1)", "stt"], 1);
