    environmentSafetyImpact: valueOf(row, ["moi truong, atvsld (vh1)", "moi truong, atvsld", "moi truong", "atvsld"], 11),
    severityRaw: valueOf(row, ["phan loai anh huong (vh1)", "phan loai anh huong", "phan loai"], 12),
    conditionRaw: valueOf(row, ["dk thuc hien (vh1)", "dieu kien thuc hien", "dk thuc hien"], 13),
    sourceStatusRaw: valueOf(row, ["ghi chu kq sua chua (vh1)", "ghi chu kq", "tinh trang khiem khuyet", "tinh trang"], 14),
    ktatReviewRaw: valueOf(row, ["ktat ra soat", "ktat"]),
