    repairOrderNumberRaw: valueOf(row, ["so pct/l ct (sccn)", "so pct/lct (sccn)", "so pct/l ct (dtd)", "so pct/lct (dtd)", "so pct/l ct", "so pct/lct"]),
    repairSolutionRaw: valueOf(row, ["giai phap sua chua (sccn)", "giai phap sua chua (dtd)", "giai phap sua chua"]),
